pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum1, uint256 minSum2, uint256 collectAmount, uint256 lockTime) public {
        vm.assume(minSum1 > 0);
        vm.assume(minSum2 < minSum1);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= minSum2);
        vm.assume(lockTime > 0);

        // Initialize
        c.Initialized();

        // Set MinSum to minSum1 (reverts in reference after initialization, succeeds in bug)
        c.SetMinSum(minSum1);

        // Set MinSum to minSum2 (reverts in reference after initialization, succeeds in bug)
        c.SetMinSum(minSum2);

        // Prepare a deposit for msg.sender
        address sender = address(this);
        vm.deal(sender, collectAmount);
        vm.prank(sender);
        c.Put{value: collectAmount}(lockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Collect
        uint256 balanceBefore = address(sender).balance;
        vm.prank(sender);
        c.Collect(collectAmount);
        uint256 balanceAfter = address(sender).balance;

        // In reference, MinSum should be 0 (default) because both SetMinSum calls reverted.
        // In bug, MinSum is minSum2, so collect succeeds.
        // If MinSum is minSum2 (bug), collect succeeds and balanceAfter > balanceBefore.
        // If MinSum is 0 (reference), collect reverts and balanceAfter == balanceBefore.
        // The reference property: if MinSum() < collectAmount, Collect reverts.
        // Here MinSum() is 0 in reference, so it should revert.
        // The bug violates this because MinSum() is minSum2 >= collectAmount, so it doesn't revert.
        assertTrue(c.MinSum() >= collectAmount || balanceAfter == balanceBefore);
    }
}

