pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 collectAmt) public {
        vm.assume(minSum <= type(uint128).max);
        vm.assume(lockTime <= type(uint128).max);
        vm.assume(collectAmt <= type(uint128).max);

        // Initialize
        c.Initialized();

        // Try to set MinSum after initialization
        try c.SetMinSum(minSum) {
            // If it succeeds in the reference, it should revert; if it doesn't revert, MinSum must have been set.
            // The bug allows this call to succeed, changing MinSum.
            // Assert that MinSum is unchanged (0) in the reference contract.
            // The reference always reverts here, so success indicates the bug.
            // Since reference never reaches this point, we assert false to indicate failure.
            assertTrue(false);
        } catch {
            // Reference reverts, so MinSum remains 0.
            assertEq(c.MinSum(), 0);
        }
    }
}

contract InvMutTest {
    C c;
    bool reentered;
    constructor(C _c) { c = _c; }
    function run(uint _am, uint _lockTime, uint _initBal) public payable {
        require(address(this).balance >= _initBal);
        require(!reentered);
        // Setup: fund this, Put to create a locked entry, then move time forward by calling Put again with lockTime 0 after wait
        // Instead, use a simpler approach: Put sufficient Ether to create balance, then Collect within reentrant callback
        c.Put{value: _initBal}(_lockTime);
        // We need unlock time passed. Since block.timestamp is current, we set _lockTime=0, so unlockTime = max(block.timestamp+0, previous)=block.timestamp, then we need block.timestamp > unlockTime impossible.
        // So we rely on MinSum sufficiently low, and we pass _am small. But unlockTime check fails.
        // Workaround: SetMinSum(0), Initialized() first, Put with _lockTime=0, then we need block.timestamp > unlockTime. That's strict >, so we need a delay or a second Put that advances unlockTime.
        // Simpler: we just test the reentrancy during Collect. We set up the contract so that actual Collect succeeds, then try to reenter. But the reentrant call must also succeed only if reentrancy protection is absent.
        // Attack: In receive, call c.Collect again. The difference: In Original, reentrant Collect reverts due to locked_; in Modified, it succeeds.
        // So we make an initial balance, call Collect with _am, in receive we call c.Collect again with smaller amount and check result.
        // We check whether reentrant call reverted. We detect by checking if balance changed or by using a bool.
        reentered = false;
        c.Collect(_am);
        // If reentered, balance may have been drained more. But we assert something observable after both calls complete.
        assert(reentered == false);
    }
    receive() external payable {
        if (msg.sender == address(c)) {
            // Reentrant call attempt
            try c.Collect(1) {
                reentered = true;
            } catch {
                reentered = false;
            }
        }
    }
}

