contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 lockTime, uint256 depositAmount, uint256 collectAmount) public {
        // Restrict inputs to admissible range for arithmetic safety
        vm.assume(lockTime <= type(uint256).max - block.timestamp);
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Initialize the contract so SetMinSum can be called later in reentrant scenario
        c.Initialized();
        // Set initial MinSum to 0 so balance check passes
        c.SetMinSum(0);

        // Prepare actor with enough balance
        address actor = address(0x1000);
        vm.deal(actor, depositAmount);

        // Actor deposits with a lock time
        vm.prank(actor);
        c.Put{value: depositAmount}(lockTime);

        // Warp past unlock time so Collect can succeed
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before Collect
        uint256 minBefore = c.MinSum();

        // Collect triggers external call to actor; re-entrant path in buggy modifies MinSum
        vm.prank(actor);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        require(success, "Collect call failed");

        // After Collect, MinSum must remain unchanged
        uint256 minAfter = c.MinSum();
        assertEq(minAfter, minBefore, "MinSum should be immutable against reentrant Collect");
