import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 amt, uint128 collectAmt) public {
        vm.assume(minSum > 0);
        vm.assume(amt < type(uint128).max - 1);
        vm.assume(collectAmt < amt);
        vm.assume(collectAmt > 0);
        vm.assume(amt >= minSum);
        vm.assume(collectAmt >= minSum);
        vm.assume(lockTime < type(uint256).max - block.timestamp);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(minSum);
        address payable logAddr = payable(makeAddr("log"));
        vm.etch(logAddr, address(new Log()).code);
        c.SetLogFile(logAddr);

        // Setup actor with funds
        vm.deal(address(this), amt);
        c.Put{value: amt}(lockTime);

        // Warp past unlock time so collect is allowed
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before collect
        uint256 minSumBefore = c.MinSum();

        // Attempt to collect
        bool ok;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // After collect (whether it succeeds or reverts), MinSum must equal its value before collect
        // because the reentrancy guard prevents any reentrant call (e.g. from the fallback) from modifying it
        assertTrue(ok ? (c.MinSum() == minSumBefore) : true);
    }

    fallback() external payable {
        // Reentrant attempt: try to change MinSum
        try c.SetMinSum(0) {} catch {}
    }

    receive() external payable {
        try c.SetMinSum(0) {} catch {}
    }
}

