import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val1, uint256 val2) public {
        // admissible: val1 != val2
        vm.assume(val1 != val2);

        // setup: deploy a minimal attacking contract that reenters SetMinSum with val2
        address attacker = address(new Attacker(c, val1, val2));
        vm.deal(attacker, 0);

        // The reference protects against reentrancy; the mutant does not.
        // After the attack, we record what MinSum is.
        vm.prank(attacker);
        c.Initialized();

        vm.prank(attacker);
        c.SetMinSum(val1);

        uint256 finalMinSum = c.MinSum();

        // RULE: MinSum, once set after initialization, remains equal to the first value passed to SetMinSum (val1).
        // The bug allows reentrancy that changes it to val2.
        assertTrue(finalMinSum == val1);
    }
}

contract Attacker {
    C public target;
    uint256 public firstVal;
    uint256 public secondVal;
    bool public entered;

    constructor(C _target, uint256 _first, uint256 _second) {
        target = _target;
        firstVal = _first;
        secondVal = _second;
    }

    fallback() external {
        if (!entered) {
            entered = true;
            target.SetMinSum(secondVal);
        }
    }
}

